return [{ json: {
  business_name: 'Acme Studio',
  who_i_am: 'Solo founder, direct and concise writer',
  positioning: 'Done-for-you brand systems for B2B SaaS',
  offer: 'Fixed-scope brand sprint, 3 tiers',
  brand_voice: 'Plain, confident, no hype',
  connectors: ['linear', 'google_drive', 'crm', 'meta_ads', 'accounting'],
  root_dir: './ai-os'
} }];

const j = $input.first().json;
if (!j.business_name) throw new Error('business_name is required');
const root = (j.root_dir || './ai-os').replace(//+$/, '');
const files = [];
files.push({ fileName: root + '/CLAUDE.md', content: ['# CLAUDE.md', '', 'Rules and preferences for ' + j.business_name + '.', '', '- Always write in this brand voice: ' + (j.brand_voice||'(define)'), '- Read context/ before any task.', '- Run repeated work via skills/.', '- Keep a human in the loop for publishing, outreach and spend.'].join('
') });
files.push({ fileName: root + '/context/profile.md', content: '# Profile

' + (j.who_i_am||'(who I am and how I talk)') });
files.push({ fileName: root + '/context/positioning.md', content: '# Positioning

' + (j.positioning||'(what I do and what sets me apart)') });
files.push({ fileName: root + '/context/offer.md', content: '# Offer

' + (j.offer||'(what I sell and how it is structured)') });
files.push({ fileName: root + '/context/brand.md', content: '# Brand guidelines

Voice: ' + (j.brand_voice||'(define)') });
files.push({ fileName: root + '/skills/README.md', content: '# Skills

One folder per routine you run more than once, so it runs the same way every time.' });
const conn = (j.connectors||[]).map(c => '- [ ] ' + c + ' (MANUAL: authorise + wire MCP/credential later)').join('
');
files.push({ fileName: root + '/connectors.md', content: ['# Connectors (manual handoffs)', '', 'MCP + memory layers and each integration are wired later, outside this scaffold:', '', conn || '- (none listed)', '', 'Document each connection and its purpose here so a new hire can run the system.'].join('
') });
return files.map(f => ({ json: f }));
